import{z as r,x as l,o,c as B,q as d,j as t,D as a,d as i,s as n,S as s}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"位操作扩展","description":"","frontmatter":{"title":"位操作扩展","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/bit-manip-ext.md","filePath":"cs/bit-manip-ext.md","lastUpdated":1791063341000}'),E={name:"cs/bit-manip-ext.md"};function p(A,e,h,b,m,C){const c=l("Mermaid");return o(),B("div",null,[e[2]||(e[2]=d('<h1 id="位操作扩展" tabindex="-1">位操作扩展 <a class="header-anchor" href="#位操作扩展" aria-label="Permalink to &quot;位操作扩展&quot;">​</a></h1><div class="epigraph"><p>移位、掩码、数前导零本可用基础整数凑出来；B 扩展与 BMI 把高频序列收成一条，地址缩放和位域插入不再占用半个循环。</p><footer>—— 据 RISC-V Bit-Manipulation ISA-extensions；Intel SDM（BMI1/BMI2）；ARM ARM；Patterson and Hennessy, Computer Organization and Design 整理</footer></div><p><a href="/cs/riscv-h-extension">上一课</a>补完特权两层翻译。用户态加法与移位仍停在 <a href="/cs/riscv-int-isa">整数指令</a>。缺口是 <strong>位操作扩展</strong>：RISC-V <code>Zba</code>/<code>Zbb</code>/<code>Zbs</code>、x86 BMI、ARM 位域，而不是再讲分页。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>编译器把 <code>a[i]</code> 写成 <code>base + i&lt;&lt;2</code>：RV32I 要移位再加。<code>Zba</code> 的 <code>sh2add</code> 一条完成。数前导零在 <a href="/cs/lzc-normalize">LZC</a> 的浮点规格化里出现过，整数侧对应 <code>clz</code>/<code>ctz</code>/<code>cpop</code>（<code>Zbb</code>）。单比特置/清/测是 <code>Zbs</code>。缺口不是「位运算是什么」，而是<strong>哪些序列被提升为 ISA</strong>，以免软件永远用移位库冒充。</p><p>x86：BMI1（<code>andn</code>、<code>tzcnt</code>、<code>blsr</code>）与 BMI2（<code>pext</code>/<code>pdep</code>、<code>shlx</code>）。ARM：<code>UBFX</code>/<code>SBFX</code>/<code>BFI</code>、<code>RBIT</code>、<code>CLZ</code>。对照课要能指到这组名字。</p><p><span class="marginnote">术语翻译：<code>clz</code> 是「从最高位往下数，数到第一个 1 为止有几个 0」，<code>ctz</code> 从最低位往上数，<code>cpop</code> 是数整串里 1 的总个数。浮点规格化、按位图的优先级调度都靠它们；没有专用指令时，这些要靠一串移位加减凑出来。</span></p><h3 id="位操作不是加密课、也不是量化权重量化" tabindex="-1">位操作不是加密课、也不是量化权重量化 <a class="header-anchor" href="#位操作不是加密课、也不是量化权重量化" aria-label="Permalink to &quot;位操作不是加密课、也不是量化权重量化&quot;">​</a></h3><p>进位无关乘法 <code>clmul</code>（<code>Zbc</code>）给 CRC 与有限域，本课点名即止，不进入密码协议。<a href="/litho/em-wave-index">光刻</a> 与金融栏不收这些助记符。把 BMI 写成「大模型推理内核」，CS 栏失焦。</p><p><span class="marginnote">RISC-V Bit-Manip 规范分 Zb* 子集。Intel SDM 卷 2 的 BMI。ARM 位域指令在 A64。本课不抄 opcode 图。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>软件：编译器在 <code>-march</code> 含 B/BMI 时选新指令，否则降级为移位序列；ABI 要标明扩展，否则目标文件在旧核上非法指令。<code>rev8</code> / <code>orc.b</code> 服务大小端与字符串探测，后课 endian 会引用。<code>min</code>/<code>max</code> 无分支比较可减少<a href="/cs/condition-codes-predication">条件码</a> 压力。</p>',12)),(o(),t(s,null,{default:a(()=>[n(c,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20SHIFT%5B%22%E7%A7%BB%E4%BD%8D%E5%8A%A0%E5%9F%BA%E5%9D%80%22%5D%20--%3E%20ZBA%5B%22Zba%20%2F%20%E7%BC%A9%E6%94%BE%E5%8A%A0%22%5D%0A%20%20MASK%5B%22%E6%8E%A9%E7%A0%81%E4%B8%8E%E6%95%B0%E4%BD%8D%22%5D%20--%3E%20ZBB%5B%22Zbb%20clz%20ctz%22%5D%0A%20%20BIT%5B%22%E5%8D%95%E6%AF%94%E7%89%B9%22%5D%20--%3E%20ZBS%5B%22Zbs%22%5D%0A%20%20ZBA%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E7%BB%93%E6%9E%9C%E8%BF%9B%E6%A0%87%E5%BF%97%E8%BF%98%E6%98%AF%E8%BF%9B%20GPR%22%5D%0A%20%20ZBB%20--%3E%20LATER%0A%20%20ZBS%20--%3E%20LATER%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[i(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=d('<p>与 <a href="/cs/simd-extensions">SIMD</a>：打包移位是通道上的同类操作；本课是标量 GPR。RVV 有向量位操作，宽度故事已在向量课。</p><p><span class="marginnote">数字实例：<code>int</code> 是 4 字节，所以 <code>a[i]</code> 的偏移是 \\(i \\times 4\\)，即 <code>i&lt;&lt;2</code>。取 <code>a[1000]</code> 就是基址加 4000 字节。没有 <code>sh2add</code> 时这是 <code>slli</code> + <code>add</code> 两条指令；有了它，地址缩放一条完成——循环里每次迭代都省一拍。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>H 扩展不改变这些编码。压缩课的 16 位别名覆盖不到全部 B 指令，多数仍是 32 位。下一课条件码：x86 几乎每条 ALU 都写 EFLAGS，RISC-V 的 <code>clz</code> 只写 GPR——谓词与分支如何接上这些结果，是对照轴上尚未钉住的缺口。</p><p>同一段源码在有无扩展的核上如何落地，可以对着看。</p>',5)),(o(),t(s,null,{default:a(()=>[n(c,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20SRC%5B%22%E6%BA%90%E7%A0%81%EF%BC%9A%E6%95%B0%E7%BB%84%E5%8F%96%E5%9D%80%20a%20of%20i%22%5D%20--%3E%20CC%5B%22%E7%BC%96%E8%AF%91%E5%99%A8%E8%AF%BB%20-march%22%5D%0A%20%20CC%20--%3E%7C%22%E6%9C%89%20Zba%22%7C%20ONE%5B%22sh2add%20%E4%B8%80%E6%9D%A1%E6%8C%87%E4%BB%A4%22%5D%0A%20%20CC%20--%3E%7C%22%E6%97%A0%20Zba%22%7C%20TWO%5B%22slli%20%2B%20add%20%E4%B8%A4%E6%9D%A1%22%5D%0A%20%20ONE%20--%3E%20RUN%5B%22%E8%AF%AD%E4%B9%89%E7%9B%B8%E5%90%8C%EF%BC%8C%E9%80%9F%E5%BA%A6%E4%B8%8E%E4%BD%93%E7%A7%AF%E4%B8%8D%E5%90%8C%22%5D%0A%20%20TWO%20--%3E%20RUN%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[i(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=d('<p><span class="marginnote">常见误区：以为位操作扩展只是「快一点」。实际上降级序列还多占指令缓存与解码带宽，而且 ABI 必须标明目标扩展——给旧核发了一个带 <code>sh2add</code> 的目标文件，跑起来直接是非法指令异常，不是慢，是不动。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不列 <code>Zb*</code> 全表，不保证某 MCU 实现了 B。不把 <code>pdep</code> 的棋盘hack 当作业。不进入 GPU 的 ballot。</p><p>后课默认：地址缩放、前导零、单比特是 ISA 扩展而不是库循环；RISC-V 用 Zb 子集，x86 用 BMI。下一课条件码与谓词。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><code>Zba</code>/<code>Zbb</code>/<code>Zbs</code> 与 BMI/位域把高频位序列收成指令。</li><li>与虚拟化正交，与 SIMD 通道正交。</li><li>结果是否进条件码，下一课。</li><li>出处：RISC-V Bit-Manipulation spec；Intel SDM；ARM ARM；Patterson and Hennessy, COD。</li></ul>',6))])}const I=r(E,[["render",p]]);export{D as __pageData,I as default};
